    input: process.stdin,
    output: process.stdout
});

readline.question('', (s) => {
    console.log(SolveProblem(s));
    readline.close();
});

function SolveProblem(s) {
    let lowerCount = 0;
    let higherCount = 0;
    for (let i = 0; i < s.length; i++) {
        if (s[i] >= 'a' && s[i] <= 'z') {
            lowerCount++;
        } else {
            higherCount++;
        }

        if (lowerCount > Math.floor(s.length / 2)) {
            return s.toLowerCase();
        }
    }
    return lowerCount === higherCount ? s.toLowerCase() : s.toUpperCase();
}

